def signals(n_trials: int, n_ch: int, n_t: int):
    X = np.zeros((n_trials, n_ch, n_t))
    for i in range(n_trials):
        for c in range(n_ch):
            for t in range(n_t):
                v = (i * 1009 + c * 7919 + t * 104729 + i * c * t * 13
                     + t * t * (c + 1) * 3 + c * c * t * 7) % 101
                X[i, c, t] = (v - 50.0) / 25.0 + ((0.5 * (i % 2)) if (c + t) % 3 == 0 else 0.0)
    return X

def spd(n_mats: int, n: int):
    out = np.zeros((n_mats, n, n))
    for k in range(n_mats):
        A = np.zeros((n, n))
        for i in range(n):
            for j in range(n):
                A[i, j] = ((i + 1) * (j + 2) * (k + 3) % 7 - 3.0) / 4.0
        out[k] = A @ A.T + (k + 1.0) * np.eye(n)
    return out

def close(got, exp: List[float], rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    ok = True
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            ok = False
    return ok

def closef(got: float, exp: float, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    if abs(got - exp) > atol + rtol * abs(exp):
        print("mismatch", got, exp)
        return False
    return True

X = signals(12, 4, 60)
cov = covariances(X, "scm")
y = np.array([i % 2 for i in range(12)])

E_d_logeuclid = [0.5251716094574473, 0.6115446497947681, 0.5219384987217676, 0.48029957410986196, 0.3682727684927808, 0.35168399273608886, 0.5464681833569481, 0.5432786410514655]
E_p_logeuclid = [0.0, 1.0, 1.0, 1.0]
E_pp_logeuclid = [0.5245257114185786, 0.4754742885814215, 0.4895684850006068, 0.5104315149993932, 0.49701423517408594, 0.5029857648259141, 0.499131052475144, 0.500868947524856]
E_d_euclid = [0.683631144793204, 0.742616291551942, 0.6825286903938181, 0.6222380240216028, 0.519852724936316, 0.4611460813406824, 0.7331882032742872, 0.7294148103149412]
E_p_euclid = [0.0, 1.0, 1.0, 1.0]
E_pp_euclid = [0.5210194580845181, 0.47898054191548184, 0.4803438216866867, 0.5196561783133132, 0.48560619133517613, 0.5143938086648239, 0.49862025952368644, 0.5013797404763135]

@test
def test_nch():
    assert close(NearestConvexHull("logeuclid").fit(cov[:8], y[:8]).transform(cov[8:]), E_d_logeuclid, atol=1e-06)
    assert close(NearestConvexHull("logeuclid").fit(cov[:8], y[:8]).predict(cov[8:]), E_p_logeuclid, atol=1e-06)
    assert close(NearestConvexHull("logeuclid").fit(cov[:8], y[:8]).predict_proba(cov[8:]), E_pp_logeuclid, atol=1e-06)
    assert close(NearestConvexHull("euclid").fit(cov[:8], y[:8]).transform(cov[8:]), E_d_euclid, atol=1e-06)
    assert close(NearestConvexHull("euclid").fit(cov[:8], y[:8]).predict(cov[8:]), E_p_euclid, atol=1e-06)
    assert close(NearestConvexHull("euclid").fit(cov[:8], y[:8]).predict_proba(cov[8:]), E_pp_euclid, atol=1e-06)
test_nch()
